@charset "UTF-8";

/* ==========================================================================
   CSSリセット & 基本変数定義
   ========================================================================== */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg-deep: #030712;
  --bg-panel: rgba(15, 23, 42, 0.78);
  --bg-panel-hover: rgba(30, 41, 59, 0.85);
  --border-subtle: rgba(255, 255, 255, 0.12);
  --border-bright: rgba(56, 189, 248, 0.4);
  --text-primary: #f8fafc;
  --text-secondary: #94a3b8;
  --text-muted: #64748b;
  --accent-cyan: #38bdf8;
  --accent-cyan-glow: rgba(56, 189, 248, 0.35);
  --accent-amber: #f59e0b;
  --accent-purple: #a855f7;
  --accent-glow: 0 0 20px rgba(56, 189, 248, 0.35);
  --shadow-panel: 0 16px 36px -4px rgba(0, 0, 0, 0.6), 0 0 0 1px var(--border-subtle);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 18px;
  --radius-pill: 9999px;
  --transition-fast: 0.18s cubic-bezier(0.16, 1, 0.3, 1);
  --transition-base: 0.28s cubic-bezier(0.16, 1, 0.3, 1);
}

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--bg-deep);
  color: var(--text-primary);
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Hiragino Sans', 'Noto Sans JP', sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

#root {
  width: 100%;
  height: 100%;
}

/* ==========================================================================
   フォーカス可視性（アクセシビリティ向上）
   ========================================================================== */
.icon-btn:focus-visible,
.planet-chip:focus-visible,
.playback-btn:focus-visible,
.toggle-btn:focus-visible,
.reset-cam-btn:focus-visible,
.info-close-btn:focus-visible,
.speed-slider-wrap input[type="range"]:focus-visible {
  outline: 2px solid var(--accent-cyan);
  outline-offset: 2px;
  box-shadow: 0 0 10px var(--accent-cyan-glow);
}

/* ==========================================================================
   アプリケーション外枠 & 3Dキャンバス
   ========================================================================== */
.solar-app {
  position: relative;
  width: 100vw;
  height: 100vh;
  overflow: hidden;
  background: radial-gradient(circle at 50% 50%, #080f24 0%, #030712 100%);
  user-select: none;
}

.canvas-container {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
  outline: none;
  cursor: grab;
}

.canvas-container:active {
  cursor: grabbing;
}

/* ==========================================================================
   UIオーバーレイ層
   ========================================================================== */
.ui-overlay {
  position: absolute;
  inset: 0;
  z-index: 10;
  pointer-events: none;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 16px 20px;
}

/* UIパーツ内はクリックを有効化 */
.top-bar,
.quick-selector,
.controls-bar,
.info-panel,
.legend-hint {
  pointer-events: auto;
}

/* ==========================================================================
   上部ヘッダーバー
   ========================================================================== */
.top-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  background: var(--bg-panel);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  padding: 10px 18px;
  box-shadow: var(--shadow-panel);
}

.app-title {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 1.15rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--text-primary);
  text-shadow: 0 0 12px rgba(255, 255, 255, 0.2);
}

.title-badge {
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--accent-cyan);
  background: rgba(56, 189, 248, 0.12);
  border: 1px solid rgba(56, 189, 248, 0.3);
  padding: 2px 8px;
  border-radius: var(--radius-pill);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 44px;
  min-height: 44px;
  width: 44px;
  height: 44px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.icon-btn:hover {
  background: rgba(255, 255, 255, 0.12);
  color: var(--text-primary);
  border-color: var(--accent-cyan);
  box-shadow: 0 0 10px var(--accent-cyan-glow);
}

/* ==========================================================================
   クイック惑星セレクター（上部直下）
   ========================================================================== */
.quick-selector {
  display: flex;
  align-items: center;
  gap: 8px;
  overflow-x: auto;
  padding: 8px 4px;
  margin-top: 10px;
  scrollbar-width: none;
}

.quick-selector::-webkit-scrollbar {
  display: none;
}

.planet-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 38px;
  padding: 8px 14px;
  background: rgba(15, 23, 42, 0.7);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-pill);
  color: var(--text-secondary);
  font-size: 0.82rem;
  font-weight: 500;
  cursor: pointer;
  white-space: nowrap;
  transition: all var(--transition-fast);
}

.planet-chip:hover {
  background: rgba(30, 41, 59, 0.9);
  color: var(--text-primary);
  border-color: rgba(255, 255, 255, 0.25);
  transform: translateY(-1px);
}

.planet-chip-active {
  background: linear-gradient(135deg, rgba(56, 189, 248, 0.25) 0%, rgba(168, 85, 247, 0.25) 100%);
  border-color: var(--accent-cyan);
  color: #ffffff;
  box-shadow: 0 0 14px var(--accent-cyan-glow), inset 0 0 8px rgba(56, 189, 248, 0.2);
  font-weight: 600;
}

/* ==========================================================================
   操作ガイド・凡例ヒント
   ========================================================================== */
.legend-hint {
  position: absolute;
  top: 120px;
  left: 20px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px 14px;
  background: rgba(15, 23, 42, 0.65);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  font-size: 0.75rem;
  color: var(--text-secondary);
  pointer-events: none;
  animation: fadeIn 0.4s ease-out;
}

.legend-hint span {
  display: flex;
  align-items: center;
  gap: 6px;
}

.legend-hint span::before {
  content: "";
  display: inline-block;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background-color: var(--accent-cyan);
  box-shadow: 0 0 6px var(--accent-cyan);
}

/* ==========================================================================
   下部コントロールバー
   ========================================================================== */
.controls-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
  background: var(--bg-panel);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 10px 20px;
  box-shadow: var(--shadow-panel);
  margin-top: auto;
}

.ctrl-group {
  display: flex;
  align-items: center;
  gap: 10px;
}

.playback-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-width: 90px;
  min-height: 44px;
  padding: 0 16px;
  background: linear-gradient(135deg, #0284c7 0%, #0369a1 100%);
  border: 1px solid rgba(56, 189, 248, 0.4);
  border-radius: var(--radius-sm);
  color: #ffffff;
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--transition-fast);
  box-shadow: 0 2px 10px rgba(2, 132, 199, 0.35);
}

.playback-btn:hover {
  filter: brightness(1.15);
  box-shadow: 0 0 16px rgba(56, 189, 248, 0.6);
  transform: translateY(-1px);
}

.playback-btn:active {
  transform: translateY(0);
}

/* 速度スライダー周り（タップターゲット44px相当を確保） */
.speed-slider-wrap {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 44px;
  background: rgba(255, 255, 255, 0.04);
  padding: 4px 12px;
  border-radius: var(--radius-sm);
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.speed-slider-wrap input[type="range"] {
  appearance: none;
  -webkit-appearance: none;
  width: 90px;
  height: 32px;
  background: transparent;
  outline: none;
  cursor: pointer;
  margin: 0;
}

.speed-slider-wrap input[type="range"]::-webkit-slider-runnable-track {
  width: 100%;
  height: 6px;
  background: rgba(255, 255, 255, 0.2);
  border-radius: 3px;
}

.speed-slider-wrap input[type="range"]::-webkit-slider-thumb {
  appearance: none;
  -webkit-appearance: none;
  width: 22px;
  height: 22px;
  margin-top: -8px;
  border-radius: 50%;
  background: var(--accent-cyan);
  box-shadow: 0 0 8px var(--accent-cyan);
  cursor: pointer;
  transition: transform var(--transition-fast);
}

.speed-slider-wrap input[type="range"]::-webkit-slider-thumb:hover {
  transform: scale(1.15);
}

.speed-slider-wrap input[type="range"]::-moz-range-track {
  width: 100%;
  height: 6px;
  background: rgba(255, 255, 255, 0.2);
  border-radius: 3px;
}

.speed-slider-wrap input[type="range"]::-moz-range-thumb {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--accent-cyan);
  box-shadow: 0 0 8px var(--accent-cyan);
  border: none;
  cursor: pointer;
}

.speed-label {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--accent-cyan);
  min-width: 38px;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

/* トグルボタン（軌道線・ラベル） */
.toggle-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 44px;
  padding: 0 14px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  font-size: 0.8rem;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.toggle-btn:hover {
  background: rgba(255, 255, 255, 0.1);
  color: var(--text-primary);
}

.toggle-btn-active {
  background: rgba(56, 189, 248, 0.15);
  border-color: var(--accent-cyan);
  color: var(--accent-cyan);
  box-shadow: 0 0 10px var(--accent-cyan-glow);
}

/* 視点リセットボタン */
.reset-cam-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 44px;
  padding: 0 14px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: 0.82rem;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.reset-cam-btn:hover {
  background: rgba(255, 255, 255, 0.12);
  border-color: rgba(255, 255, 255, 0.3);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}

/* ==========================================================================
   右側天体詳細情報パネル
   ========================================================================== */
.info-panel {
  position: absolute;
  top: 80px;
  right: 20px;
  width: 340px;
  max-height: calc(100vh - 170px);
  background: var(--bg-panel);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-panel);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  animation: slideInRight 0.3s cubic-bezier(0.16, 1, 0.3, 1);
  z-index: 20;
}

@keyframes slideInRight {
  from {
    opacity: 0;
    transform: translateX(20px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

.info-panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 18px;
  border-bottom: 1px solid var(--border-subtle);
  background: rgba(255, 255, 255, 0.02);
}

.info-panel-header h2 {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-primary);
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.info-panel-header h2 span {
  font-size: 0.78rem;
  font-weight: 400;
  color: var(--text-muted);
}

/* 閉じるボタン（44px以上のタップ領域を確保） */
.info-close-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 44px;
  min-height: 44px;
  width: 44px;
  height: 44px;
  background: transparent;
  border: none;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  font-size: 1.1rem;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.info-close-btn:hover {
  background: rgba(255, 255, 255, 0.1);
  color: var(--text-primary);
}

.info-body {
  padding: 16px 18px;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.info-body::-webkit-scrollbar {
  width: 5px;
}

.info-body::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.2);
  border-radius: 3px;
}

/* メタ情報グリッド（直径、公転周期など） */
.info-meta-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
}

.meta-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: var(--radius-sm);
  padding: 8px 10px;
}

.meta-label {
  font-size: 0.7rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.meta-val {
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--text-primary);
}

.info-desc {
  font-size: 0.85rem;
  line-height: 1.6;
  color: #cbd5e1;
  background: rgba(0, 0, 0, 0.25);
  border-radius: var(--radius-sm);
  padding: 12px;
  border: 1px solid rgba(255, 255, 255, 0.05);
}

/* ==========================================================================
   アニメーション & レスポンシブ最適化
   ========================================================================== */
@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 768px) {
  .ui-overlay {
    padding: 10px 12px;
  }

  .top-bar {
    padding: 8px 12px;
  }

  .app-title {
    font-size: 1rem;
  }

  .title-badge {
    display: none;
  }

  .legend-hint {
    display: none; /* スマホ画面の視認性確保のため省略 */
  }

  .info-panel {
    top: auto;
    bottom: 84px;
    right: 12px;
    left: 12px;
    width: auto;
    max-height: 55vh;
    padding-bottom: env(safe-area-inset-bottom, 0px);
  }

  .info-panel-header {
    padding: 8px 14px;
  }

  .info-body {
    padding: 12px 14px;
    gap: 12px;
  }

  .info-desc {
    font-size: 0.82rem;
    padding: 10px;
  }

  .controls-bar {
    padding: 8px 12px;
    gap: 8px;
    justify-content: center;
  }

  .speed-slider-wrap {
    padding: 2px 8px;
  }

  .speed-slider-wrap input[type="range"] {
    width: 64px;
  }
}

export interface MoonData {
  id: string;
  name: string;
  englishName: string;
  radius: number;
  distance: number;
  speed: number;
  color: string;
}

export interface CelestialBody {
  id: string;
  name: string;
  englishName: string;
  radius: number;
  distance: number;
  speed: number;
  rotationSpeed: number;
  axialTilt?: number; // 自転軸傾斜角（度数法）
  orbitInclination?: number; // 軌道傾斜角（度数法）
  color: string;
  emissive?: string;
  hasRings?: boolean;
  ringInnerRadius?: number;
  ringOuterRadius?: number;
  ringColor?: string;
  description: string;
  diameterKm: string;
  orbitPeriodDays: string;
  rotationPeriodHours: string;
  distanceFromSunKm: string;
  moonsCount: number;
  moons?: MoonData[];
}

export type CameraViewMode = 'overview' | 'follow';

export interface SimulationSettings {
  isPlaying: boolean;
  speedMultiplier: number;
  showOrbits: boolean;
  showLabels: boolean;
  viewMode?: CameraViewMode;
}

import { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { CelestialBody, MoonData, SimulationSettings } from '../types';

interface SolarSystemCanvasProps {
  planets?: CelestialBody[];
  selectedPlanetId?: string | null;
  onSelectPlanet?: (id: string | null) => void;
  settings?: SimulationSettings;
}

interface MoonMeshObject {
  id: string;
  data: MoonData;
  mesh: THREE.Mesh;
  orbitLine: THREE.Line;
  currentAngle: number;
}

interface PlanetMeshObject {
  id: string;
  body: CelestialBody;
  mesh: THREE.Mesh;
  group: THREE.Group; // 公転用グループ（原点中心）
  satelliteGroup?: THREE.Group; // 衛星用グループ（惑星位置に同期）
  orbitLine: THREE.Line;
  labelSprite?: THREE.Sprite;
  labelTexture?: THREE.CanvasTexture;
  currentAngle: number;
  moons?: MoonMeshObject[];
}

const SolarSystemCanvas = ({
  planets = [],
  selectedPlanetId = null,
  onSelectPlanet,
  settings = {
    isPlaying: true,
    speedMultiplier: 1,
    showOrbits: true,
    showLabels: true,
  },
}: SolarSystemCanvasProps) => {
  const containerRef = useRef<HTMLDivElement>(null);

  // Three.js 内部オブジェクトの参照保持
  const refs = useRef<{
    scene: THREE.Scene;
    camera: THREE.PerspectiveCamera;
    renderer: THREE.WebGLRenderer;
    planetObjects: PlanetMeshObject[];
    isInteracting: boolean;
    prevPointer: { x: number; y: number };
    spherical: THREE.Spherical;
    targetFocus: THREE.Vector3;
    currentFocus: THREE.Vector3;
    cameraDistance: number;
    targetCameraDistance: number;
    reqId: number | null;
  } | null>(null);

  // settingsの変更をThreeのレンダリングループから安全に参照するためのRef
  const settingsRef = useRef(settings);
  useEffect(() => {
    settingsRef.current = settings;
    // 軌道線・衛星軌道線・ラベルの即時可視性反映
    if (refs.current) {
      refs.current.planetObjects.forEach((po) => {
        po.orbitLine.visible = settings.showOrbits;
        if (po.moons) {
          po.moons.forEach((mo) => {
            mo.orbitLine.visible = settings.showOrbits;
          });
        }
        if (po.labelSprite) {
          po.labelSprite.visible = settings.showLabels;
        }
      });
    }
  }, [settings]);

  // selectedPlanetIdの変更を安全に参照するためのRef
  const selectedPlanetIdRef = useRef(selectedPlanetId);
  useEffect(() => {
    selectedPlanetIdRef.current = selectedPlanetId;
    if (refs.current) {
      if (!selectedPlanetId) {
        refs.current.targetFocus.set(0, 0, 0);
        refs.current.targetCameraDistance = 110;
      } else {
        const found = refs.current.planetObjects.find((p) => p.id === selectedPlanetId);
        if (found) {
          const bodyRadius = found.body.radius;
          refs.current.targetCameraDistance = Math.max(bodyRadius * 4.5, 12);
        }
      }
    }
  }, [selectedPlanetId]);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const width = container.clientWidth || window.innerWidth;
    const height = container.clientHeight || window.innerHeight;

    // 1. シーン構築
    const scene = new THREE.Scene();
    scene.fog = new THREE.FogExp2(0x030712, 0.0012);

    // 2. カメラ構築
    const camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 2000);
    const initialSpherical = new THREE.Spherical(110, Math.PI / 3, Math.PI / 4);
    camera.position.setFromSpherical(initialSpherical);

    // 3. レンダラー構築
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, powerPreference: 'high-performance' });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.2;
    container.innerHTML = '';
    container.appendChild(renderer.domElement);

    // 4. 照明設定
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.25);
    scene.add(ambientLight);

    const sunPointLight = new THREE.PointLight(0xffffff, 2.2, 800, 0.4);
    sunPointLight.position.set(0, 0, 0);
    scene.add(sunPointLight);

    // 5. 背景の星空パーティクル
    const starCount = 3500;
    const starGeometry = new THREE.BufferGeometry();
    const starPositions = new Float32Array(starCount * 3);
    const starColors = new Float32Array(starCount * 3);

    const colorA = new THREE.Color(0xffffff);
    const colorB = new THREE.Color(0x93c5fd);
    const colorC = new THREE.Color(0xfef08a);

    for (let i = 0; i < starCount; i++) {
      const i3 = i * 3;
      const radius = 500 + Math.random() * 800;
      const theta = 2 * Math.PI * Math.random();
      const phi = Math.acos(2 * Math.random() - 1);

      starPositions[i3] = radius * Math.sin(phi) * Math.cos(theta);
      starPositions[i3 + 1] = radius * Math.sin(phi) * Math.sin(theta);
      starPositions[i3 + 2] = radius * Math.cos(phi);

      const mixed = Math.random();
      const choice = mixed < 0.7 ? colorA : mixed < 0.9 ? colorB : colorC;
      starColors[i3] = choice.r;
      starColors[i3 + 1] = choice.g;
      starColors[i3 + 2] = choice.b;
    }
    starGeometry.setAttribute('position', new THREE.BufferAttribute(starPositions, 3));
    starGeometry.setAttribute('color', new THREE.BufferAttribute(starColors, 3));

    const starMaterial = new THREE.PointsMaterial({
      size: 1.8,
      vertexColors: true,
      transparent: true,
      opacity: 0.85,
    });
    const starPoints = new THREE.Points(starGeometry, starMaterial);
    scene.add(starPoints);

    // テキストスプライト生成ヘルパー
    const createLabelSprite = (text: string): { sprite: THREE.Sprite; texture: THREE.CanvasTexture } => {
      const canvas = document.createElement('canvas');
      canvas.width = 256;
      canvas.height = 64;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.fillStyle = 'rgba(15, 23, 42, 0.8)';
        ctx.beginPath();
        if (typeof ctx.roundRect === 'function') {
          ctx.roundRect(10, 10, 236, 44, 20);
        } else {
          ctx.rect(10, 10, 236, 44);
        }
        ctx.fill();
        ctx.lineWidth = 2;
        ctx.strokeStyle = 'rgba(56, 189, 248, 0.5)';
        ctx.stroke();

        ctx.font = 'bold 22px -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif';
        ctx.fillStyle = '#ffffff';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(text, 128, 32);
      }
      const texture = new THREE.CanvasTexture(canvas);
      texture.minFilter = THREE.LinearFilter;
      const spriteMaterial = new THREE.SpriteMaterial({ map: texture, transparent: true, depthTest: false });
      const sprite = new THREE.Sprite(spriteMaterial);
      sprite.scale.set(7, 1.75, 1);
      return { sprite, texture };
    };

    // 6. 天体メッシュ群の構築
    const planetObjects: PlanetMeshObject[] = [];

    planets.forEach((body) => {
      const orbitGroup = new THREE.Group();
      scene.add(orbitGroup);

      // 球体メッシュ作成
      const sphereGeo = new THREE.SphereGeometry(body.radius, 32, 32);
      let material: THREE.Material;

      if (body.id === 'sun') {
        material = new THREE.MeshBasicMaterial({
          color: new THREE.Color(body.color),
        });
      } else {
        material = new THREE.MeshStandardMaterial({
          color: new THREE.Color(body.color),
          roughness: 0.65,
          metalness: 0.15,
        });
      }

      const mesh = new THREE.Mesh(sphereGeo, material);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      mesh.position.x = body.distance;
      orbitGroup.add(mesh);

      // 太陽コロナグロー
      if (body.id === 'sun') {
        const glowGeo = new THREE.SphereGeometry(body.radius * 1.25, 32, 32);
        const glowMat = new THREE.MeshBasicMaterial({
          color: 0xffaa33,
          transparent: true,
          opacity: 0.25,
          side: THREE.BackSide,
        });
        const glowMesh = new THREE.Mesh(glowGeo, glowMat);
        mesh.add(glowMesh);
      }

      // 土星などの輪
      if (body.hasRings && body.ringInnerRadius && body.ringOuterRadius) {
        const ringGeo = new THREE.RingGeometry(body.ringInnerRadius, body.ringOuterRadius, 64);
        const ringMat = new THREE.MeshStandardMaterial({
          color: new THREE.Color(body.ringColor || '#e2d4a8'),
          side: THREE.DoubleSide,
          transparent: true,
          opacity: 0.85,
          roughness: 0.5,
        });
        const ringMesh = new THREE.Mesh(ringGeo, ringMat);
        ringMesh.rotation.x = Math.PI * 0.45;
        ringMesh.rotation.y = Math.PI * 0.1;
        mesh.add(ringMesh);
      }

      // 軌道ライン (LineLoop)
      const orbitCurve = new THREE.EllipseCurve(0, 0, body.distance, body.distance, 0, 2 * Math.PI, false, 0);
      const orbitPoints = orbitCurve.getPoints(120);
      const orbitGeo = new THREE.BufferGeometry().setFromPoints(
        orbitPoints.map((p) => new THREE.Vector3(p.x, 0, p.y))
      );
      const orbitMat = new THREE.LineBasicMaterial({
        color: 0x38bdf8,
        transparent: true,
        opacity: body.distance === 0 ? 0 : 0.28,
      });
      const orbitLine = new THREE.Line(orbitGeo, orbitMat);
      scene.add(orbitLine);
      orbitLine.visible = settingsRef.current.showOrbits;

      // 衛星（ムーン）の構築
      let satelliteGroup: THREE.Group | undefined;
      const moonMeshList: MoonMeshObject[] = [];

      if (body.moons && body.moons.length > 0) {
        satelliteGroup = new THREE.Group();
        satelliteGroup.position.copy(mesh.position);
        scene.add(satelliteGroup);

        body.moons.forEach((m) => {
          // 衛星の軌道線
          const moonOrbitCurve = new THREE.EllipseCurve(0, 0, m.distance, m.distance, 0, 2 * Math.PI, false, 0);
          const moonOrbitPts = moonOrbitCurve.getPoints(64);
          const moonOrbitGeo = new THREE.BufferGeometry().setFromPoints(
            moonOrbitPts.map((p) => new THREE.Vector3(p.x, 0, p.y))
          );
          const moonOrbitMat = new THREE.LineBasicMaterial({
            color: 0x94a3b8,
            transparent: true,
            opacity: 0.22,
          });
          const moonOrbitLine = new THREE.Line(moonOrbitGeo, moonOrbitMat);
          moonOrbitLine.visible = settingsRef.current.showOrbits;
          satelliteGroup!.add(moonOrbitLine);

          // 衛星球体メッシュ
          const moonGeo = new THREE.SphereGeometry(m.radius, 16, 16);
          const moonMat = new THREE.MeshStandardMaterial({
            color: new THREE.Color(m.color),
            roughness: 0.75,
            metalness: 0.1,
          });
          const moonMesh = new THREE.Mesh(moonGeo, moonMat);
          moonMesh.castShadow = true;
          moonMesh.receiveShadow = true;
          moonMesh.position.x = m.distance;
          satelliteGroup!.add(moonMesh);

          moonMeshList.push({
            id: m.id,
            data: m,
            mesh: moonMesh,
            orbitLine: moonOrbitLine,
            currentAngle: Math.random() * Math.PI * 2,
          });
        });
      }

      // ラベルスプライト
      let labelSprite: THREE.Sprite | undefined;
      let labelTexture: THREE.CanvasTexture | undefined;
      if (body.id !== 'sun') {
        const labelObj = createLabelSprite(body.name);
        labelSprite = labelObj.sprite;
        labelTexture = labelObj.texture;
        labelSprite.position.set(0, body.radius + 2.5, 0);
        mesh.add(labelSprite);
        labelSprite.visible = settingsRef.current.showLabels;
      }

      planetObjects.push({
        id: body.id,
        body,
        mesh,
        group: orbitGroup,
        satelliteGroup,
        orbitLine,
        labelSprite,
        labelTexture,
        currentAngle: Math.random() * Math.PI * 2,
        moons: moonMeshList.length > 0 ? moonMeshList : undefined,
      });
    });

    // 内部ステート初期化
    refs.current = {
      scene,
      camera,
      renderer,
      planetObjects,
      isInteracting: false,
      prevPointer: { x: 0, y: 0 },
      spherical: initialSpherical,
      targetFocus: new THREE.Vector3(0, 0, 0),
      currentFocus: new THREE.Vector3(0, 0, 0),
      cameraDistance: 110,
      targetCameraDistance: 110,
      reqId: null,
    };

    // 7. マウス・タッチ操作（OrbitControls相当の軽量実装）
    const onPointerDown = (e: PointerEvent) => {
      if (e.button !== 0 && e.pointerType === 'mouse') return;
      if (!refs.current) return;
      refs.current.isInteracting = true;
      refs.current.prevPointer = { x: e.clientX, y: e.clientY };
    };

    const onPointerMove = (e: PointerEvent) => {
      if (!refs.current || !refs.current.isInteracting) return;
      const dx = e.clientX - refs.current.prevPointer.x;
      const dy = e.clientY - refs.current.prevPointer.y;
      refs.current.prevPointer = { x: e.clientX, y: e.clientY };

      const rotateSpeed = 0.005;
      refs.current.spherical.theta -= dx * rotateSpeed;
      refs.current.spherical.phi -= dy * rotateSpeed;

      // 仰角制限 (真上・真下でのフリップ防止)
      refs.current.spherical.phi = Math.max(0.08, Math.min(Math.PI - 0.08, refs.current.spherical.phi));
    };

    const onPointerUp = () => {
      if (!refs.current) return;
      refs.current.isInteracting = false;
    };

    const onWheel = (e: WheelEvent) => {
      e.preventDefault();
      if (!refs.current) return;
      const zoomFactor = 1 + e.deltaY * 0.0012;
      refs.current.targetCameraDistance = THREE.MathUtils.clamp(
        refs.current.targetCameraDistance * zoomFactor,
        6,
        350
      );
    };

    // レイキャストクリック判定
    const raycaster = new THREE.Raycaster();
    const mouseVector = new THREE.Vector2();

    const onClick = (e: MouseEvent) => {
      if (!refs.current || !container) return;
      const rect = container.getBoundingClientRect();
      mouseVector.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
      mouseVector.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;

      raycaster.setFromCamera(mouseVector, refs.current.camera);
      const meshesToTest = refs.current.planetObjects.map((po) => po.mesh);
      const intersects = raycaster.intersectObjects(meshesToTest, false);

      if (intersects.length > 0) {
        const hitMesh = intersects[0].object as THREE.Mesh;
        const matched = refs.current.planetObjects.find((po) => po.mesh === hitMesh);
        if (matched) {
          onSelectPlanet?.(matched.id);
        }
      }
    };

    const domElement = renderer.domElement;
    domElement.addEventListener('pointerdown', onPointerDown);
    window.addEventListener('pointermove', onPointerMove);
    window.addEventListener('pointerup', onPointerUp);
    domElement.addEventListener('wheel', onWheel, { passive: false });
    domElement.addEventListener('click', onClick);

    // リサイズハンドラ
    const handleResize = () => {
      if (!container || !refs.current) return;
      const w = container.clientWidth;
      const h = container.clientHeight;
      refs.current.camera.aspect = w / h;
      refs.current.camera.updateProjectionMatrix();
      refs.current.renderer.setSize(w, h);
    };
    window.addEventListener('resize', handleResize);

    // 8. メインレンダリングループ
    let lastTime = performance.now();
    const animate = (time: number) => {
      const delta = Math.min((time - lastTime) / 1000, 0.1);
      lastTime = time;

      const state = refs.current;
      if (!state) return;

      const currentSettings = settingsRef.current;
      const currentSelectedId = selectedPlanetIdRef.current;

      // 惑星および衛星の公転・自転
      state.planetObjects.forEach((po) => {
        if (currentSettings.isPlaying) {
          const moveDelta = po.body.speed * currentSettings.speedMultiplier * delta * 2.5;
          po.currentAngle += moveDelta;
          po.mesh.position.x = Math.cos(po.currentAngle) * po.body.distance;
          po.mesh.position.z = Math.sin(po.currentAngle) * po.body.distance;
          po.mesh.rotation.y += po.body.rotationSpeed * delta * 60;

          // 衛星の公転
          if (po.moons && po.moons.length > 0) {
            po.moons.forEach((mo) => {
              const moonMoveDelta = mo.data.speed * currentSettings.speedMultiplier * delta * 2.5;
              mo.currentAngle += moonMoveDelta;
              mo.mesh.position.x = Math.cos(mo.currentAngle) * mo.data.distance;
              mo.mesh.position.z = Math.sin(mo.currentAngle) * mo.data.distance;
            });
          }
        }

        // 衛星グループの位置を親惑星の座標に同期
        if (po.satelliteGroup) {
          po.satelliteGroup.position.copy(po.mesh.position);
        }

        // 選択惑星の場合はフォーカスターゲットを惑星のワールド座標へ追従
        if (currentSelectedId === po.id) {
          po.mesh.getWorldPosition(state.targetFocus);
        }
      });

      // 惑星追従時: ユーザーのドラッグ回転と目標位置追従が競合して揺れないよう、
      // 選択中は直接追従、未選択時はスムーズ補間(Lerp)で原点へ復帰
      if (currentSelectedId) {
        state.currentFocus.copy(state.targetFocus);
      } else {
        state.currentFocus.lerp(state.targetFocus, 0.06);
      }

      state.cameraDistance = THREE.MathUtils.lerp(state.cameraDistance, state.targetCameraDistance, 0.08);
      state.spherical.radius = state.cameraDistance;

      // カメラ位置決定 (独立した球面座標オフセットをターゲット位置に加算)
      const camOffset = new THREE.Vector3().setFromSpherical(state.spherical);
      state.camera.position.copy(state.currentFocus).add(camOffset);
      state.camera.lookAt(state.currentFocus);

      state.renderer.render(state.scene, state.camera);
      state.reqId = requestAnimationFrame(animate);
    };

    refs.current.reqId = requestAnimationFrame(animate);

    // クリーンアップ
    return () => {
      if (refs.current?.reqId) {
        cancelAnimationFrame(refs.current.reqId);
      }
      domElement.removeEventListener('pointerdown', onPointerDown);
      window.removeEventListener('pointermove', onPointerMove);
      window.removeEventListener('pointerup', onPointerUp);
      domElement.removeEventListener('wheel', onWheel);
      domElement.removeEventListener('click', onClick);
      window.removeEventListener('resize', handleResize);

      // 惑星・衛星関連リソースの完全な破棄（球体・リング・軌道線・衛星・スプライト・テクスチャ）
      planetObjects.forEach((po) => {
        // メッシュおよび子要素の走査破棄
        po.mesh.traverse((child) => {
          if (child instanceof THREE.Mesh || child instanceof THREE.Sprite) {
            if (child.geometry) {
              child.geometry.dispose();
            }
            if (child.material) {
              if (Array.isArray(child.material)) {
                child.material.forEach((m) => m.dispose());
              } else {
                child.material.dispose();
              }
            }
          }
        });

        // 衛星メッシュ・衛星軌道線の破棄
        if (po.satelliteGroup) {
          po.satelliteGroup.traverse((child) => {
            if (child instanceof THREE.Mesh || child instanceof THREE.Line) {
              if (child.geometry) {
                child.geometry.dispose();
              }
              if (child.material) {
                if (Array.isArray(child.material)) {
                  child.material.forEach((m) => m.dispose());
                } else {
                  child.material.dispose();
                }
              }
            }
          });
        }

        // 軌道ラインの破棄
        if (po.orbitLine) {
          if (po.orbitLine.geometry) {
            po.orbitLine.geometry.dispose();
          }
          if (po.orbitLine.material) {
            if (Array.isArray(po.orbitLine.material)) {
              po.orbitLine.material.forEach((m) => m.dispose());
            } else {
              po.orbitLine.material.dispose();
            }
          }
        }

        // ラベル用 CanvasTexture の破棄
        if (po.labelTexture) {
          po.labelTexture.dispose();
        }
      });

      starGeometry.dispose();
      starMaterial.dispose();
      renderer.dispose();
      if (container.contains(domElement)) {
        container.removeChild(domElement);
      }
    };
  }, [planets, onSelectPlanet]);

  return (
    <div className="canvas-container" ref={containerRef}>
      <div className="legend-hint">
        <span>ドラッグで視点回転</span>
        <span>ホイールでズームイン・アウト</span>
        <span>惑星クリックで接近フォーカス</span>
      </div>
    </div>
  );
};

