              className={settings.showLabels ? 'toggle-btn toggle-btn-active' : 'toggle-btn'}
              aria-pressed={settings.showLabels}
              onClick={toggleLabels}
            >
              <Tag size={16} />
              <span>ラベル</span>
            </button>

            <button
              type="button"
              className="reset-cam-btn"
              onClick={handleResetCamera}
              title="視点を太陽系全体に戻す"
              aria-label="視点を太陽系全体に戻す"
            >
              <RotateCcw size={15} />
              <span>視点リセット</span>
            </button>
          </div>
        </footer>
      </div>
    </div>
  );
};

export default App;
